SELECT FROM sys_user
is_deleted = 0
AND username LIKE CONCAT('%', #{q.username}, '%')
AND real_name LIKE CONCAT('%', #{q.realName}, '%')
AND status = #{q.status}
ORDER BY id DESC LIMIT #{offset}, #{q.size}

